from typing import List

def countComponents(nums: List[int], threshold: int) -> int:
    parent = {}

    def find(i):
        if parent[i] == i: return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    # Only numbers <= threshold can have any edge
    valid_nums = [x for x in nums if x <= threshold]
    # Map value to index/existence for fast lookup
    exists = set(valid_nums)

    for x in valid_nums:
        parent[x] = x

    # Iterate through all possible multiples up to threshold
    # If i and j are connected, there exists a common multiple m <= threshold
    # such that lcm(i, j) = (i*j)/gcd(i, j) <= threshold.
    # This is equivalent to saying i and j both divide some value k where 
    # we can link them via their divisors.

    # Optimization: If lcm(a, b) <= threshold, then a and b are connected.
    # We can connect every x to all its multiples m <= threshold.
    # If x divides m, then lcm(x, m) = m. Since m <= threshold, they are connected.
    for i in range(1, threshold + 1):
        if i in exists:
            for j in range(2 * i, threshold + 1, i):
                if j in exists:
                    union(i, j)

    # Count components for numbers <= threshold
    count = 0
    for x in valid_nums:
        if parent[x] == x:
            count += 1

    # Every number > threshold is its own isolated component
    return count + (len(nums) - len(valid_nums))
