    # This is a classic Maximum Subarray Sum problem (Kadane's) for each unique x
    max_gain = 0

    # To handle the "k" subtraction correctly, we treat nums as a sequence of scores:
    # If we pick value x, score is +1. If we encounter k, score is -1.
    for x in diffs:
        current_gain = 0
        best_x_gain = 0
        for val in nums:
            if val == x:
                current_gain += 1
            elif val == k:
                current_gain -= 1

            if current_gain < 0:
                current_gain = 0
            best_x_gain = max(best_x_gain, current_gain)

        max_gain = max(max_gain, best_x_gain)

    return initial_k + max_gain
