def maxFrequency(nums: List[int], k: int) -> int:
    initial_k_count = 0
    for x in nums:
        if x == k:
            initial_k_count += 1

    max_gain = 0
    # We want to find a subarray that maximizes (count of v - count of k)
    # for any value v != k.
    # Because we only perform one operation on one subarray, and the goal is to make elements equal to k,
    # changing a range [i, j] by x makes all current values 'v' where v + x = k into k.
    # This means for a fixed target value v, every occurrence of v in the range becomes k,
    # and every existing k in that range becomes something else (not k).

    # We iterate through all possible unique values v != k present in nums.
    unique_elements = set(nums)
    for v in unique_elements:
        if v == k:
            continue

        current_gain = 0
        max_v_gain = 0
        # Kadane's style: 
        # Treat v as +1, treat k as -1.
        for x in nums:
            if x == v:
                current_gain += 1
            elif x == k:
                current_gain -= 1

            if current_gain < 0:
                current_gain = 0
            if current_gain > max_v_gain:
                max_v_gain = current_gain

        if max_v_gain > max_gain:
            max_gain = max_v_gain

    return initial_k_count + max_gain
