def getLargestOutlier(nums: List[int]) -> int:
    total_sum = sum(nums)
    counts = collections.Counter(nums)
    candidates = []
    for s in counts:
        x = total_sum - 2 * s
        if s == x:
            if counts[s] >= 2:
                # The remaining n-2 elements must sum to s.
                # Sum of all others = Total_Sum - s - x = (2s + x) - s - x = s.
                candidates.append(x)
        else:
            if counts[s] >= 1 and counts[x] >= 1:
                candidates.append(x)
