def countKReducibleNumbers(s: str, k: int) -> int:
    MOD = 10**9 + 7
    L = len(s)

    # Precompute combinations C(n, r)
    C = [[0] * (L + 1) for _ in range(L + 1)]
    for i in range(L + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD

    # Precompute if a count 'c' is k-reducible to 1
    def is_reducible(num, steps):
        if num == 1: return True
        if steps == 0: return False
        count = bin(num).count('1')
        return is_reducible(count, steps - 1)

    # Check all possible set bit counts from 1 to L
    is_k_red = [False] * (L + 1)
    for i in range(1, L + 1):
        if is_reducible(i, k):
            is_k_red[i] = True

    # Digit DP: count numbers < n with exactly 'bits' set bits
    ans = 0
    current_bits = 0
    for i in range(L):
        if s[i] == '1':
            # If we put a '0' at this position, remaining positions can be anything
            remaining_pos = L - 1 - i
            for bits_to_add in range(remaining_pos + 1):
                total_bits = current_bits + bits_to_add
                if total_bits > 0 and is_k_red[total_bits]:
                    ans = (ans + C[remaining_pos][bits_to_add]) % MOD
            current_bits += 1

    return ans
