def longestPalindromicSubsequence(s: str, k: int) -> int:
    n = len(s)

    @functools.lru_cache(None)
    def solve(i: int, j: int, rem_k: int) -> int:
        if i > j:
            return 0
        if i == j:
            return 1

        # Option 1: Skip the left character
        res = solve(i + 1, j, rem_k)
        # Option 2: Skip the right character
        res = max(res, solve(i, j - 1, rem_k))

        # Option 3: Try to match s[i] and s[j]
        diff = abs(ord(s[i]) - ord(s[j]))
        cost = min(diff, 26 - diff)

        if cost <= rem_k:
            res = max(res, 2 + solve(i + 1, j - 1, rem_k - cost))

        return res

    return solve(0, n - 1, k)
