from collections import deque
from typing import List

def maxMoves(kx: int, ky: int, positions: List[List[int]]) -> int:
    # 預先計算所有點到起始點以及彼此的距離 (BFS)
    # 因為棋盤是 50x50，且主教移動規則固定，可以用 BFS 求最短路徑
    dist_matrix = [[0] * len(positions) for _ in range(len(positions))]
    all_points = [(kx, ky)] + positions
    n = len(positions)

    # 建立距離矩陣：從每個點到所有其他點的最短路徑
    def get_distances(start_pos):
        dists = {}
        queue = deque([(start_pos, 0)])
        visited = {start_pos}
        while queue:
            (x, y), d = queue.popleft()
            dists[(x, y)] = d
            for dx, dy in [(2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 50 and 0 <= ny < 50 and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), d + 1))
        return dists

    # 計算從起始點到每個主教的距離，以及主教之間的距離
    point_dists = []
    for i in range(len(positions)):
        point_dists.append(get_distances(positions[i]))

    start_dist = get_distances((kx, ky))

    # 建立一個二維陣列，記錄點與點之間的距離 (包含起始點)
    # index 0 是起始點，1~n 是主教
    adj = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        # 起始點到主教 i
        adj[0][i+1] = start_dist.get(positions[i], float('inf'))
        adj[i+1][0] = adj[0][i+1]
        for j in range(n):
            if i != j:
                # 主教 i 到 主教 j
                adj[i+1][j+1] = point_dists[i].get(positions[j], float('inf'))

    memo = {}

    def solve(current_pos_idx, mask):
        if mask == (1 << n) - 1:
            return 0
        if (current_pos_idx, mask) in memo:
            return memo[(current_pos_idx, mask)]

        # Alice wants to maximize, Bob wants to minimize
        # If number of bits set is even, it's Alice's turn (since she goes first at 0 bits)
        bits_set = bin(mask).count('1')
        is_alice = (bits_set % 2 == 0)

        res = float('-inf') if is_alice else float('inf')

        for i in range(n):
            if not (mask & (1 << i)):
                # Move to pawn i
                cost = adj[current_pos_idx][i+1]
                score = cost + solve(i+1, mask | (1 << i))

                if is_alice:
                    res = max(res, score)
                else:
                    res = min(res, score)

        memo[(current_pos_idx, mask)] = res
        return res

    # 從起始點 0 開始，初始遮罩為 0
    return solve(0, 0)
