        res = float('-inf') if is_alice else float('inf')

        for i in range(len(positions)):
            if not (mask & (1 << i)):
                # pawn 索引為 i 對應到 all_points 的索引為 i + 1
                d = dist_matrix[curr_idx][i + 1]
                next_val = solve(i + 1, mask | (1 << i), not is_alice)

                if is_alice:
                    res = max(res, d + next_val)
                else:
                    res = min(res, d + next_val)

        memo[state] = res
        return res

    # 起始點是 kx, ky (index 0)，初始 mask 為 0，Alice 先手
    return solve(0, 0, True)
